  kind
  name
  description
  fields {
    name
    description
    args {
      name
      description
      type {
        available
        type
        kind
        name
        description
        fields {
          name
          description
          args {
            name
            description
            type {
              available
              type
              kind
              name
              description
              fields {
                ...FullType
              }
            }
          }
        }
      }
    }
  }
  inputFields {
    name
    description
    type {
      available
      type
      kind
      name
      description
      fields {
        ...FullType
      }
    }
  }
  interfaces {
    fields {
      name
      description
      args {
        name
        description
        type {
          available
          type
          kind
          name
          description
          fields {
            ...FullType
          }
        }
      }
    }
  }
  possibleTypes {
    name
    description
    kind
    fields {
      name
      description
      args {
        name
        description
        type {
          available
          type
          kind
          name
          description
          fields {
            ...FullType
          }
        }
      }
    }
  }
  enumValues {
    name
    description
    kind
    fields {
      name
      description
      args {
        name
        description
        type {
          available
          type
          kind
          name
          description
          fields {
            ...FullType
          }
        }
      }
    }
  }
  unionTypes {
    possibleTypes {
      name
      description
      kind
      fields {
        name
        description
        args {
          name
          description
          type {
            available
            type
            kind
            name
            description
            fields {
              ...FullType
            }
          }
        }
      }
    }
  }
}

